def _ledger(data, sequence_first, tax_original, refunds):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = raw if tax_original else net
        tax = _round(base * event.get("tax_bp", 0), mode)
        value = net + tax
        if refunds and event.get("kind") == "refund":
            value = -value
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + value
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best = None
    best_key = None

    def visit(assigned, bounds):
        nonlocal best, best_key
        unresolved = [name for name in bounds if name not in assigned]
        if not unresolved:
            edges = {}
            for name, row in assigned.items():
                edges[name] = [d["name"] for d in row.get("deps", [])
                               if (not d.get("feature") or d["feature"] in features)]
            done, active = set(), set()
            def acyclic(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not acyclic(child) for child in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True
            if not all(acyclic(name) for name in edges):
                return
            names = sorted(packages, reverse=True)
            key = tuple(assigned[n]["version"] if n in assigned else -1 for n in names)
            if best_key is None or key < best_key:
                best_key = key
                best = {n: row["version"] for n, row in assigned.items()}
            return

        # Constrained-first branching reduces the search without affecting ordering.
        candidates_by_name = {}
        for name in unresolved:
            low, high = bounds[name]
            rows = [r for r in packages.get(name, [])
                    if low <= r["version"] <= high
                    and r["version"] not in blocked.get(name, [])
                    and (name not in pins or r["version"] == pins[name])]
            candidates_by_name[name] = rows
        name = min(unresolved, key=lambda n: len(candidates_by_name[n]))
        low, high = bounds[name]
        for row in candidates_by_name[name]:
            ver = row["version"]
            new_assigned = dict(assigned)
            new_assigned[name] = row
            new_bounds = dict(bounds)
            possible = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                lo, hi = dep["min"], dep["max"]
                if child in new_bounds:
                    lo = max(lo, new_bounds[child][0])
                    hi = min(hi, new_bounds[child][1])
                if lo > hi:
                    possible = False
                    break
                new_bounds[child] = (lo, hi)
                if child in new_assigned and not lo <= new_assigned[child]["version"] <= hi:
                    possible = False
                    break
            if possible:
                visit(new_assigned, new_bounds)

    initial = {name: tuple(bounds) for name, bounds in data.get("roots", {}).items()}
    visit({}, initial)
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked or len(mandatory) > k:
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    eligible = [j for j in jobs if j["id"] not in blocked]
    best = None
    best_value = None
    n = len(eligible)
    # Enumerating all masks is small (at most 2^14) and handles arbitrary quotas/ties.
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [eligible[i] for i in range(n) if mask >> i & 1]
        ids = [j["id"] for j in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for j in selected:
            counts[j["group"]] = counts.get(j["group"], 0) + 1
        if any(not (lo <= counts.get(group, 0) <= hi)
               for group, (lo, hi) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda j: (j["start"], j["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        names = sorted(ids)
        value = sum(j["value"] for j in selected)
        if (best is None or value > best_value
                or (value == best_value and names > best)):
            best, best_value = names, value
    if best is None:
        return {"error": "impossible"}
    return {"selected": best, "value": best_value}


def _component_08(data):
    import heapq
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit.get(start_node, 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (start_node, initial_mask, 0)
    dist = {initial: data["start"]}
    queue = [(data["start"], start_node, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, next_used)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, next_used))
    return {"arrival": None}


